const body = $('Webhook').first().json.body || $('Webhook').first().json || {};
const message = String(body.message || body.text || '').trim();
const history = Array.isArray(body.history) ? body.history : [];
const patient = body.patient && typeof body.patient === 'object' ? body.patient : {};
const msg = message.toLowerCase();

// FIX 2026-07-30 (safety: false-negative risk).
// negated() used msg.match(re), which returns only the FIRST match. In
// "no chest pain but crushing chest pressure" the first match is negated, so
// the genuine emergency was suppressed. Now every match is checked and the
// rule fires if ANY occurrence is un-negated. A missed MI costs far more than
// an interrupted conversation, so this errs toward firing.
function hasUnnegatedMatch(re) {
  const g = new RegExp(re.source, re.flags.includes('g') ? re.flags : re.flags + 'g');
  let m;
  while ((m = g.exec(msg)) !== null) {
    const before = msg.slice(Math.max(0, m.index - 40), m.index);
    // FIX 2026-07-30: a negation does not carry across a clause boundary.
    // "no chest pain BUT crushing chest pressure" was being suppressed because
    // the lookbehind window still contained the earlier "no". Only the nearest
    // clause counts.
    const seg = before.split(/[,;.!?]|\bbut\b|\bhowever\b|\balthough\b|\bthough\b/i).pop() || '';
    const negator = /\b(no|not|without|denies|denied|never|don'?t have|doesn'?t have)\b/.test(seg);
    // Third-person suppression is deliberately narrow: only PAST-TENSE family
    // history is suppressed. "my father HAD chest pain last year" is history;
    // "my father IS HAVING chest pain" is an emergency and must still fire.
    const thirdPartyHistory =
      /\b(my|his|her|their)\s+\w*\s*(father|mother|dad|mum|mom|brother|sister|friend|husband|wife|son|daughter|uncle|aunt)\s+(had|has had|used to have)\b/.test(seg)
      || /\b(family history|history of|hx of)\b/.test(seg);
    if (!negator && !thirdPartyHistory) return true;
    if (m.index === g.lastIndex) g.lastIndex++;
  }
  return false;
}

const rules = [
  {
    re: /chest (pain|pressure|tightness)|crushing (chest|pressure)|elephant (on|sitting)|pain radiating to (left )?arm|jaw pain.{0,30}(sweat|sweating|nausea)/i,
    crisis_type: 'acs_chest_pain',
    message: 'These symptoms can be a medical emergency. Call 911 or go to the ER now. Do not drive yourself.',
  },
  {
    re: /worst headache of (my|his|her) life|thunderclap|sudden(ly)? (severe|worst|excruciating|blinding|intense) headache|headache.{0,25}(came on|hit me|started).{0,15}(suddenly|instantly|out of nowhere)|headache with (neck stiffness|confusion|weakness|vision loss)/i,
    crisis_type: 'thunderclap_headache',
    message: 'A sudden worst-of-life headache can be an emergency. Call 911 or go to the ER now.',
  },
  {
    re: /(throat (is )?tight|lip swelling|tongue swelling|anaphylaxis|cannot breathe after|wheezing after (peanut|shellfish|bee|sting))/i,
    crisis_type: 'anaphylaxis',
    message: 'This may be anaphylaxis. Use epinephrine if available and call 911 immediately.',
  },
  {
    re: /(cannot breathe|can't breathe|blue lips|gasping for air|oxygen (sat|saturation).{0,12}(8\d|9[0-2])\b)/i,
    crisis_type: 'respiratory_distress',
    message: 'Severe breathing problems need emergency care. Call 911 or go to the ER now.',
  },
  {
    re: /(severe (lower|right lower) (abdominal|belly|stomach) pain|rigid abdomen|pain so bad I (can'?t|cannot) walk).{0,40}(fever|vomiting)?|(sudden severe abdominal pain)/i,
    crisis_type: 'surgical_abdomen',
    message: 'Severe abdominal pain with these features can be a surgical emergency. Seek ER care now.',
  },
];

let hit = null;
for (const rule of rules) {
  if (hasUnnegatedMatch(rule.re)) {
    hit = rule;
    break;
  }
}

if (hit) {
  return [{
    json: {
      route: 'force_end',
      status: 'force_end',
      risk_level: 'emergency',
      crisis_type: hit.crisis_type,
      force_end: true,
      is_emergency: true,
      care_setting: 'call_911',
      message: hit.message,
      red_flags: [hit.crisis_type],
      source: 'deterministic',
      message_text: message,
      history,
      patient,
    }
  }];
}

return [{
  json: {
    route: 'llm',
    status: 'needs_llm',
    force_end: false,
    is_emergency: false,
    message_text: message,
    history,
    patient,
  }
}];

