const pre = $('Deterministic Prefilter').first().json;
const raw = $input.first().json || {};
const parsed = raw.output || raw;

const status = String(parsed.status || (parsed.force_end ? 'force_end' : 'pass')).toLowerCase();
const force_end = !!(parsed.force_end || status === 'force_end');
const risk_level = String(parsed.risk_level || (force_end ? 'emergency' : 'low')).toLowerCase();
const crisis_type = String(parsed.crisis_type || (force_end ? 'other_emergency' : 'none'));
const care_setting = String(parsed.care_setting || (force_end ? 'call_911' : 'home'));
const message = String(parsed.message || (force_end
  ? 'Please call emergency services immediately.'
  : 'No emergency detected.'));
const red_flags = Array.isArray(parsed.red_flags) ? parsed.red_flags : [];

return [{
  json: {
    status: force_end ? 'force_end' : (status === 'high_risk_continue' ? 'high_risk_continue' : 'pass'),
    risk_level,
    crisis_type,
    force_end,
    is_emergency: force_end,
    care_setting,
    message,
    red_flags,
    source: 'llm',
  }
}];

